import math

def qmul(a, b):
    w1, x1, y1, z1 = a
    w2, x2, y2, z2 = b
    return (w1*w2 - x1*x2 - y1*y2 - z1*z2,
            w1*x2 + x1*w2 + y1*z2 - z1*y2,
            w1*y2 - x1*z2 + y1*w2 + z1*x2,
            w1*z2 + x1*y2 - y1*x2 + z1*w2)

def qaxis(n, deg):
    L = math.sqrt(sum(t*t for t in n))
    h = math.radians(deg) / 2
    s = math.sin(h) / L
    return (math.cos(h), n[0]*s, n[1]*s, n[2]*s)

def qnorm(q):
    L = math.sqrt(sum(t*t for t in q))
    return tuple(t / L for t in q)

def aci(q):
    return round(2 * math.degrees(math.acos(min(1.0, abs(q[0])))), 2)

def slerp(a, b, t):
    d = sum(a[i]*b[i] for i in range(4))
    if d < 0:
        b = tuple(-x for x in b); d = -d
    th = math.acos(min(1.0, d))
    if th < 1e-6:
        return a
    s = math.sin(th)
    return tuple(math.sin((1-t)*th)/s * a[i] + math.sin(t*th)/s * b[i] for i in range(4))

