import math

P = [(0.0, 0.0), (1.0, 3.0), (4.0, 3.0), (5.0, 0.0)]

def lerp(a, b, t):
    return (a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t)

def casteljau(P, t):
    pts, seviye = list(P), [list(P)]
    while len(pts) > 1:
        pts = [lerp(pts[i], pts[i + 1], t) for i in range(len(pts) - 1)]
        seviye.append(list(pts))
    return pts[0], seviye

