def bern(P, t):
    x = sum(math.comb(3, i) * (1 - t) ** (3 - i) * t ** i * P[i][0] for i in range(4))
    y = sum(math.comb(3, i) * (1 - t) ** (3 - i) * t ** i * P[i][1] for i in range(4))
    return (round(x, 6), round(y, 6))

