def turev(P, t):
    d = [(P[i+1][0] - P[i][0], P[i+1][1] - P[i][1]) for i in range(3)]
    x = 3 * ((1-t)**2 * d[0][0] + 2*(1-t)*t * d[1][0] + t*t * d[2][0])
    y = 3 * ((1-t)**2 * d[0][1] + 2*(1-t)*t * d[1][1] + t*t * d[2][1])
    return (round(x, 6), round(y, 6), round(math.hypot(x, y), 6))

