import math

L1, L2 = 3.0, 2.0

def ik(x, y, yukari=True):
    r2 = x*x + y*y
    r = math.sqrt(r2)
    if r > L1 + L2 or r < abs(L1 - L2):
        return None
    c2 = max(-1.0, min(1.0, (r2 - L1*L1 - L2*L2) / (2*L1*L2)))
    th2 = math.acos(c2) if yukari else -math.acos(c2)
    k1 = L1 + L2*math.cos(th2)
    k2 = L2*math.sin(th2)
    th1 = math.atan2(y, x) - math.atan2(k2, k1)
    return round(math.degrees(th1), 4), round(math.degrees(th2), 4)

def fk(t1, t2):
    a, b = math.radians(t1), math.radians(t1 + t2)
    return round(L1*math.cos(a) + L2*math.cos(b), 4), round(L1*math.sin(a) + L2*math.sin(b), 4)

