def MT(th, tx, ty):
    c, s = math.cos(math.radians(th)), math.sin(math.radians(th))
    return [[c, -s, tx], [s, c, ty]]

def ap(M, p):
    return (M[0][0]*p[0] + M[0][1]*p[1] + M[0][2],
            M[1][0]*p[0] + M[1][1]*p[1] + M[1][2])

